# Cutoffs are source syntax, not authored numeric outputs.
src=bundles['mle.decision_threshold_selection']['teaching_blocks'][1]['content']
TEXT['decision_threshold_selection'][1]=TEXT['decision_threshold_selection'][1].format(probability_cutoff=re.search(r'use a ([\d.]+) cutoff',src).group(1),decision_cutoff=re.search(r'and decision_function scores a (\w+) cutoff',src).group(1))

# API syntax is lifted from the fact bank; numeric defaults are never retyped.
spread_facts = [f['statement'] for bundle in G['bundles'] for f in bundle['coverage']['required_facts'] if 'np.std(numeric_values' in f['statement']]
spread = spread_facts[0]
pop_api = re.search(r'np\.std\(numeric_values, ddof=\d+\)', spread).group()
sample_ddof = re.search(r'use (ddof=\d+)', spread).group(1)
for name, blocks in TEXT.items():
 for i, text in enumerate(blocks):
  text = re.sub(r'np\.mean(?!\()', 'np.mean(numeric_values)', text)
  text = re.sub(r'np\.std(?!\()', pop_api, text)
  text = text.replace('N−1', 'N−1 ('+sample_ddof+')') if 'np.std' in text else text
  blocks[i] = text
exec((B/"finish_screens.py").read_text())
